package main

import "fmt"

// LadderLength returns the number of words in the shortest transformation
// from beginWord to endWord, changing one letter at a time with every
// intermediate word in the list (0 if impossible). BFS over the implicit
// word graph; neighbors are generated by trying all 26 letters per position.
func LadderLength(beginWord, endWord string, wordList []string) int {
	dict := make(map[string]bool, len(wordList))
	for _, w := range wordList {
		dict[w] = true
	}
	if !dict[endWord] {
		return 0
	}
	queue := []string{beginWord}
	delete(dict, beginWord) // never revisit
	steps := 1
	buf := []byte{}
	for len(queue) > 0 {
		next := []string{}
		for _, w := range queue {
			if w == endWord {
				return steps
			}
			buf = append(buf[:0], w...)
			for i := 0; i < len(buf); i++ {
				orig := buf[i]
				for c := byte('a'); c <= 'z'; c++ {
					if c == orig {
						continue
					}
					buf[i] = c
					cand := string(buf)
					if dict[cand] {
						delete(dict, cand) // claimed at the earliest level
						next = append(next, cand)
					}
				}
				buf[i] = orig
			}
		}
		queue = next
		steps++
	}
	return 0
}

func main() {
	fmt.Println(LadderLength("hit", "cog", []string{"hot", "dot", "dog", "lot", "log", "cog"}))
	fmt.Println(LadderLength("hit", "cog", []string{"hot", "dot", "dog", "lot", "log"}))
}
